#!/usr/bin/env python3
"""OmniPath-style bounded probe round replay and uncertainty-aware evidence analysis.

Reads one JSON document from stdin, writes one JSON document to stdout.
Standard library only, Python 3.11.
"""

import heapq
import json
import re
import sys

LABEL_RE = re.compile(r"\A[a-z0-9]{1,8}\Z")
JSON_WS = " \t\n\r"
MAX_INPUT_BYTES = 2097152
MAX_PATHS = 8192

PRIO_RELEASE = 1
PRIO_PING = 2
PRIO_ACK = 3
PRIO_TIMEOUT = 4
PRIO_HOSTACK = 5


class InvalidInput(Exception):
    pass


# ---------------------------------------------------------------- parsing ---


def _object_pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise InvalidInput("duplicate object key")
        obj[key] = value
    return obj


def _reject_constant(name):
    raise InvalidInput("non-finite JSON constant")


def parse_document(text):
    decoder = json.JSONDecoder(
        object_pairs_hook=_object_pairs, parse_constant=_reject_constant
    )
    index = 0
    length = len(text)
    while index < length and text[index] in JSON_WS:
        index += 1
    obj, end = decoder.raw_decode(text, index)
    for ch in text[end:]:
        if ch not in JSON_WS:
            raise InvalidInput("trailing data after JSON value")
    return obj


def _is_int(value):
    return type(value) is int


def validate(doc):
    if not isinstance(doc, dict):
        raise InvalidInput("root must be an object")
    if set(doc.keys()) != {"version", "n", "capacity", "edges", "rounds"}:
        raise InvalidInput("unexpected root keys")

    version = doc["version"]
    if not _is_int(version) or version != 1:
        raise InvalidInput("bad version")

    n = doc["n"]
    if not _is_int(n) or n < 2 or n > 96:
        raise InvalidInput("bad n")

    capacity = doc["capacity"]
    if not isinstance(capacity, list) or len(capacity) != n:
        raise InvalidInput("bad capacity")
    for value in capacity:
        if not _is_int(value) or value < 0 or value > 48:
            raise InvalidInput("bad capacity value")

    raw_edges = doc["edges"]
    if not isinstance(raw_edges, list) or len(raw_edges) > 384:
        raise InvalidInput("bad edges")
    edges = []
    seen_pairs = set()
    for raw in raw_edges:
        if not isinstance(raw, dict):
            raise InvalidInput("bad edge")
        if set(raw.keys()) != {"u", "v", "ping_us", "ack_us", "label"}:
            raise InvalidInput("bad edge keys")
        u = raw["u"]
        v = raw["v"]
        if not _is_int(u) or not _is_int(v):
            raise InvalidInput("bad edge endpoints")
        if u < 0 or v >= n or u >= v:
            raise InvalidInput("bad edge endpoints")
        if (u, v) in seen_pairs:
            raise InvalidInput("duplicate edge")
        seen_pairs.add((u, v))
        ping_us = raw["ping_us"]
        ack_us = raw["ack_us"]
        if not _is_int(ping_us) or ping_us < 1 or ping_us > 10000:
            raise InvalidInput("bad ping_us")
        if not _is_int(ack_us) or ack_us < 1 or ack_us > 10000:
            raise InvalidInput("bad ack_us")
        label = raw["label"]
        if not isinstance(label, str) or not LABEL_RE.match(label):
            raise InvalidInput("bad label")
        edges.append((u, v, ping_us, ack_us, label))

    raw_rounds = doc["rounds"]
    if not isinstance(raw_rounds, list) or len(raw_rounds) > 48:
        raise InvalidInput("bad rounds")
    rounds = []
    for raw in raw_rounds:
        if not isinstance(raw, dict):
            raise InvalidInput("bad round")
        if set(raw.keys()) != {
            "launch_us",
            "timeout_us",
            "host_delay_us",
            "drop_host_ack",
            "drop_ping",
            "drop_ack",
        }:
            raise InvalidInput("bad round keys")
        launch = raw["launch_us"]
        timeout = raw["timeout_us"]
        host_delay = raw["host_delay_us"]
        if not _is_int(launch) or launch < 0 or launch > 1000000000:
            raise InvalidInput("bad launch_us")
        if not _is_int(timeout) or timeout < 1 or timeout > 1000000:
            raise InvalidInput("bad timeout_us")
        if not _is_int(host_delay) or host_delay < 1 or host_delay > 10000:
            raise InvalidInput("bad host_delay_us")
        if not isinstance(raw["drop_host_ack"], bool):
            raise InvalidInput("bad drop_host_ack")
        drop_ping = raw["drop_ping"]
        drop_ack = raw["drop_ack"]
        if not isinstance(drop_ping, list) or not isinstance(drop_ack, list):
            raise InvalidInput("bad drop list")
        for lst in (drop_ping, drop_ack):
            for item in lst:
                if not _is_int(item) or item < 0 or item >= len(edges):
                    raise InvalidInput("bad drop edge id")
            if len(set(lst)) != len(lst):
                raise InvalidInput("duplicate drop edge id")
        rounds.append(
            (
                launch,
                timeout,
                host_delay,
                bool(raw["drop_host_ack"]),
                frozenset(drop_ping),
                frozenset(drop_ack),
            )
        )

    return n, capacity, edges, rounds


# --------------------------------------------------------------- replay -----


class Entry:
    __slots__ = (
        "proof",
        "credited",
        "child_complete",
        "parents",
        "finalized",
        "complete",
        "frozen",
    )

    def __init__(self):
        self.proof = set()
        self.credited = set()
        self.child_complete = {}
        self.parents = set()
        self.finalized = False
        self.complete = None
        self.frozen = frozenset()


def simulate(n, capacity, edges, rounds):
    num_rounds = len(rounds)
    out_edges = [[] for _ in range(n)]
    for eid, (u, v, _p, _a, _l) in enumerate(edges):
        out_edges[u].append(eid)

    deadlines = [launch + timeout for (launch, timeout, _h, _d, _dp, _da) in rounds]

    entries = {}
    round_nodes = [set() for _ in range(num_rounds)]
    node_count = [0] * n
    total_entries = 0
    cache_peak = [0] * n
    peak_entries = 0

    network_ping_tx = 0
    network_ack_tx = 0
    host_ack_tx = 0
    deduplicated_ping = 0
    capacity_drops = 0
    late_ping = 0
    ignored_ack = 0
    allocations = 0

    started = [False] * num_rounds
    source_final_us = [None] * num_rounds
    source_complete = [None] * num_rounds
    host_delivery_us = [None] * num_rounds
    source_proof = [frozenset() for _ in range(num_rounds)]

    heap = []
    counter = 0

    def push(time, prio, rid, key, kind, payload=None):
        nonlocal counter
        counter += 1
        heapq.heappush(heap, (time, prio, rid, key, counter, kind, payload))

    def transmit_ack(rid, eid, proof, complete, now):
        nonlocal network_ack_tx
        network_ack_tx += 1
        if eid not in rounds[rid][5]:
            push(now + edges[eid][3], PRIO_ACK, rid, eid, "ack", (proof, complete))

    def finalize(rid, node, entry, complete, now):
        nonlocal host_ack_tx
        entry.finalized = True
        entry.complete = complete
        entry.frozen = frozenset(entry.proof)
        for parent_edge in entry.parents:
            transmit_ack(rid, parent_edge, entry.frozen, complete, now)
        if node == 0:
            source_final_us[rid] = now
            source_complete[rid] = complete
            source_proof[rid] = entry.frozen
            host_ack_tx += 1
            if not rounds[rid][3]:
                push(now + rounds[rid][2], PRIO_HOSTACK, rid, -1, "hostack")

    for rid in range(num_rounds):
        push(rounds[rid][0], PRIO_PING, rid, -1, "ping")
        push(deadlines[rid] + 1, PRIO_RELEASE, rid, -1, "release")

    end_us = 0
    while heap:
        now, _prio, rid, key, _seq, kind, payload = heapq.heappop(heap)
        end_us = now

        if kind == "release":
            nodes = round_nodes[rid]
            for node in nodes:
                del entries[(rid, node)]
                node_count[node] -= 1
                total_entries -= 1
            nodes.clear()
            continue

        if kind == "ping":
            if key == -1:
                node = 0
                eid = None
            else:
                eid = key
                node = edges[eid][1]
            if now > deadlines[rid]:
                late_ping += 1
                continue
            entry = entries.get((rid, node))
            if entry is not None:
                deduplicated_ping += 1
                if eid is not None:
                    entry.parents.add(eid)
                    if entry.finalized:
                        transmit_ack(rid, eid, entry.frozen, entry.complete, now)
                continue
            if node_count[node] >= capacity[node]:
                capacity_drops += 1
                continue
            allocations += 1
            entry = Entry()
            entries[(rid, node)] = entry
            round_nodes[rid].add(node)
            node_count[node] += 1
            total_entries += 1
            if total_entries > peak_entries:
                peak_entries = total_entries
            if node_count[node] > cache_peak[node]:
                cache_peak[node] = node_count[node]
            if eid is not None:
                entry.parents.add(eid)
            push(deadlines[rid], PRIO_TIMEOUT, rid, node, "timeout")
            for out_eid in out_edges[node]:
                network_ping_tx += 1
                if out_eid not in rounds[rid][4]:
                    push(now + edges[out_eid][2], PRIO_PING, rid, out_eid, "ping")
            if not out_edges[node]:
                finalize(rid, node, entry, True, now)
            continue

        if kind == "ack":
            eid = key
            node = edges[eid][0]
            entry = entries.get((rid, node))
            if entry is None or entry.finalized or eid in entry.credited:
                ignored_ack += 1
                continue
            proof, complete = payload
            entry.credited.add(eid)
            entry.child_complete[eid] = complete
            entry.proof |= proof
            entry.proof.add(eid)
            if len(entry.credited) == len(out_edges[node]):
                finalize(rid, node, entry, all(entry.child_complete.values()), now)
            continue

        if kind == "timeout":
            node = key
            entry = entries.get((rid, node))
            if entry is None or entry.finalized:
                continue
            finalize(rid, node, entry, False, now)
            continue

        if kind == "hostack":
            host_delivery_us[rid] = now
            continue

    return {
        "started": started,
        "source_final_us": source_final_us,
        "source_complete": source_complete,
        "host_delivery_us": host_delivery_us,
        "source_proof": source_proof,
        "metrics": {
            "host_probe_tx": num_rounds,
            "network_ping_tx": network_ping_tx,
            "network_ack_tx": network_ack_tx,
            "host_ack_tx": host_ack_tx,
            "deduplicated_ping": deduplicated_ping,
            "capacity_drops": capacity_drops,
            "late_ping": late_ping,
            "ignored_ack": ignored_ack,
            "allocations": allocations,
            "cache_peak": cache_peak,
            "peak_entries": peak_entries,
            "end_us": end_us,
        },
    }


# -------------------------------------------------------------- evidence ----


def enumerate_paths(n, edges, out_edges):
    paths = []
    path = []
    stack = [(0, 0)]
    # iterative DFS over the DAG (edges always go from lower to higher node id)
    def walk(node):
        if node == n - 1:
            paths.append(tuple(path))
            return
        for eid in out_edges[node]:
            path.append(eid)
            walk(edges[eid][1])
            path.pop()

    walk(0)
    return paths


def build_classes(n, edges, out_edges, proof_of_round, delivered):
    paths = enumerate_paths(n, edges, out_edges)
    if len(paths) > MAX_PATHS:
        raise InvalidInput("too many source-to-destination paths")

    groups = {}
    path_sets = []
    signatures = []
    for path in paths:
        sig = tuple(edges[eid][4] for eid in path)
        path_set = frozenset(path)
        signatures.append(sig)
        path_sets.append(path_set)
        groups.setdefault(sig, []).append((path, path_set))

    evidence = {sig: set() for sig in groups}
    for rid in range(len(proof_of_round)):
        if not delivered[rid]:
            continue
        proof = proof_of_round[rid]
        for idx, sig in enumerate(signatures):
            if sig in evidence and rid not in evidence[sig]:
                if path_sets[idx] <= proof:
                    evidence[sig].add(rid)

    classes = []
    for sig in sorted(groups):
        members = groups[sig]
        count = len(members)
        rounds_seen = sorted(evidence[sig])
        if not rounds_seen:
            state = "unobserved"
        elif count == 1:
            state = "unique"
        else:
            state = "ambiguous"
        if count == 1:
            witnesses = [list(members[0][0])]
        else:
            witnesses = [list(members[0][0]), list(members[1][0])]
        classes.append(
            {
                "signature": list(sig),
                "candidate_count": count,
                "evidence_rounds": rounds_seen,
                "state": state,
                "candidate_witnesses": witnesses,
            }
        )

    observable = len(classes)
    observed = sum(1 for c in classes if c["evidence_rounds"])
    unique_observed = sum(1 for c in classes if c["state"] == "unique")
    ambiguous_observed = sum(1 for c in classes if c["state"] == "ambiguous")
    upper = sum(c["candidate_count"] for c in classes if c["evidence_rounds"])
    if observable == 0:
        coverage = "no-routes"
    elif observed == 0:
        coverage = "no-evidence"
    elif observed == observable:
        coverage = "complete"
    else:
        coverage = "partial"

    summary = {
        "topology_paths": len(paths),
        "observable_classes": observable,
        "observed_classes": observed,
        "unique_observed_classes": unique_observed,
        "ambiguous_observed_classes": ambiguous_observed,
        "path_evidence_lower": observed,
        "path_evidence_upper": upper,
        "coverage_status": coverage,
    }
    return classes, summary


# ------------------------------------------------------------------ main ----


def build_output(doc):
    n, capacity, edges, rounds = validate(doc)
    result = simulate(n, capacity, edges, rounds)

    num_rounds = len(rounds)
    started = result["started"]
    for rid in range(num_rounds):
        if result["source_final_us"][rid] is not None:
            started[rid] = True

    out_edges = [[] for _ in range(n)]
    for eid, (u, v, _p, _a, _l) in enumerate(edges):
        out_edges[u].append(eid)

    delivered = [result["host_delivery_us"][rid] is not None for rid in range(num_rounds)]
    classes, summary = build_classes(
        n, edges, out_edges, result["source_proof"], delivered
    )

    rounds_out = []
    for rid in range(num_rounds):
        proof = result["source_proof"][rid]
        rounds_out.append(
            {
                "id": rid,
                "started": bool(started[rid]),
                "source_final_us": result["source_final_us"][rid],
                "source_complete": result["source_complete"][rid],
                "host_delivery_us": result["host_delivery_us"][rid],
                "source_proof": sorted(proof),
            }
        )

    return {
        "rounds": rounds_out,
        "metrics": result["metrics"],
        "classes": classes,
        "summary": summary,
    }


def fail_invalid():
    sys.stdout.write('{"error":"invalid-input"}\n')
    sys.stdout.flush()
    raise SystemExit(2)


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        fail_invalid()
    if len(raw) > MAX_INPUT_BYTES:
        fail_invalid()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        fail_invalid()
    try:
        doc = parse_document(text)
        output = build_output(doc)
    except InvalidInput:
        fail_invalid()
    except RecursionError:
        fail_invalid()
    except Exception:
        fail_invalid()
    sys.stdout.write(json.dumps(output, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")
    sys.stdout.flush()
    raise SystemExit(0)


if __name__ == "__main__":
    main()
